function registerMelhorEnvioRoutes(app2) {
  app2.get("/api/melhor-envio/status", async (_req, res) => {
    try {
      const info = await getMelhorEnvioAccountInfo();
      res.json({
        success: true,
        authMode: "fixed_jwt",
        ...info
      });
    } catch (err2) {
      res.status(500).json({
        success: false,
        connected: false,
        error: err2.message || "Erro ao obter status do Melhor Envio"
      });
    }
  });
  app2.post(["/api/shipping/calculate", "/api/shipping/quote"], async (req2, res) => {
    try {
      const { cep, cepDestino, toPostalCode, postalCode, items, cartTotal } = req2.body;
      const targetCep = cep || cepDestino || toPostalCode || postalCode;
      if (!targetCep) {
        return res.status(400).json({
          success: false,
          error: "CEP de destino n\xE3o informado."
        });
      }
      const result = await calculateMelhorEnvioShipping({
        toPostalCode: targetCep,
        items,
        cartTotal
      });
      res.json(result);
    } catch (err2) {
      res.status(500).json({
        success: false,
        error: err2.message || "Erro ao calcular frete com Melhor Envio"
      });
    }
  });
  app2.get("/api/shipping/track/:code", async (req2, res) => {
    const code = req2.params.code.trim().toUpperCase();
    try {
      const token = await getValidMelhorEnvioToken();
      if (token) {
        const resTracking = await fetch(`${MELHOR_ENVIO_API_URL}/me/shipment/tracking`, {
          method: "POST",
          headers: {
            "Accept": "application/json",
            "Content-Type": "application/json",
            "Authorization": `Bearer ${token}`,
            "User-Agent": USER_AGENT
          },
          body: JSON.stringify({ orders: [code] })
        });
        if (resTracking.ok) {
          const trackingData = await resTracking.json();
          return res.json({
            success: true,
            code,
            provider: "melhor-envio",
            data: trackingData
          });
        }
      }
      const isCorreios = /^[A-Z]{2}\d{9}[A-Z]{2}$/.test(code);
      const isJadlog = /^\d{14}$/.test(code);
      res.json({
        success: true,
        code,
        provider: isCorreios ? "correios" : isJadlog ? "jadlog" : "melhor-envio",
        trackingUrl: isCorreios ? `https://rastreamento.correios.com.br/app/index.php?codigo=${code}` : isJadlog ? `https://www.jadlog.com.br/jadlog/tracking?cte=${code}` : `https://melhorenvio.com.br/rastreio/${code}`,
        message: "C\xF3digo de rastreamento oficial ativo e despachado."
      });
    } catch (err2) {
      res.status(500).json({
        success: false,
        error: err2.message || "Erro ao rastrear envio"
      });
    }
  });
  app2.post("/api/melhor-envio/webhook", (req2, res) => {
    console.log("[Melhor Envio Webhook] Event received:", JSON.stringify(req2.body));
    res.status(200).json({ received: true });
  });
}

